// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function testFuzz_property(address recipient) public {
        uint256 amount = 1 ether;
        vm.deal(address(c), amount);
        vm.prank(address(this));
        bool ok;
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            assertEq(address(c).balance, 0, "Contract balance should be zero after successful withdrawal");
        }
    }
}
